import{c as a,$ as e,Q as o,j as i,g as l,o as r,n,m as d}from"./chunks/framework.Ce_49mA8.js";const v=JSON.parse('{"title":"Склад готовой продукции (Товары)","description":"Полное руководство по учету готовых изделий, партионному учету ФИФО, двойной себестоимости, оприходованию и инвентаризации в ОмниКрафт ЕРП.","frontmatter":{"title":"Склад готовой продукции (Товары)","description":"Полное руководство по учету готовых изделий, партионному учету ФИФО, двойной себестоимости, оприходованию и инвентаризации в ОмниКрафт ЕРП.","datePublished":"2026-11-15","dateModified":"2026-11-25","order":8},"headers":[],"relativePath":"ru/docs/spaces/production/showcase.md","filePath":"ru/docs/spaces/production/showcase.md","lastUpdated":1795564800000}'),g={name:"ru/docs/spaces/production/showcase.md"},c={id:"товары-склад-готовои-продукции-и-партии-фифо",tabindex:"-1"};function p(h,t,u,f,m,b){const s=e("DocIcon");return o(),i("div",null,[l("h1",c,[r(s,{name:"showcase"}),t[0]||(t[0]=n(" Товары: Склад готовой продукции и партии ФИФО ",-1)),t[1]||(t[1]=l("a",{class:"header-anchor",href:"#товары-склад-готовои-продукции-и-партии-фифо","aria-label":'Permalink to "Товары: Склад готовой продукции и партии ФИФО"'},"​",-1))]),t[2]||(t[2]=d('<p>В ремесленном бизнесе и штучном производстве готовая продукция на полке представляет собой овеществленный оборотный капитал мастерской. Пока изделие не передано в руки покупателя, в каждом стежке, шлифованном срезе и капле защитного воска заморожены реальные деньги: стоимость израсходованного сырья, оплата рабочего времени мастера и доля накладных расходов мастерской.</p><p>Если учет готовых товаров ведется бессистемно или в общей таблице, создатель неизбежно сталкивается с потерей контроля: старые изделия продаются по новым ценам, фактическая себестоимость партий размывается, а витрина вводит клиентов в заблуждение неактуальными складскими остатками.</p><p>Вкладка <strong>«Товары»</strong> в <strong>ОмниКрафт ЕРП</strong> служит центральным складским реестром готовой продукции. Сюда автоматически зачисляются изделия, выпущенные на Верстаке, здесь отражается фактический физический остаток мастерской, контролируются замороженные партии и формируются розничные цены для продажи.</p><hr><h2 id="режимы-отображения-и-навигация-по-складу" tabindex="-1">Режимы отображения и навигация по складу <a class="header-anchor" href="#режимы-отображения-и-навигация-по-складу" aria-label="Permalink to &quot;Режимы отображения и навигация по складу&quot;">​</a></h2><p>Интерфейс складского учета готовых изделий спроектирован для мгновенной оценки остатков и быстрой инвентаризации. В правой части панели инструментов расположены элементы управления рабочим пространством:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Складские строки (режим по умолчанию):</strong> компактный операционный реестр с квадратными миниатюрами (1:1), точным количеством единиц на полке, фактической средневзвешенной себестоимостью, расчетной ценой и блоком быстрых кнопок действий в каждой строке. Идеален для ежедневного учета большого ассортимента.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Карточки изделий (плиточная сетка):</strong> просторная визуальная витрина с крупными фотографиями и развернутыми параметрами. Удобна для визуальной ревизии склада, демонстрации каталога заказчикам и проверки оформления позиций.</div></li></ul><h3 id="фильтрация-склада-и-быстрыи-поиск" tabindex="-1">Фильтрация склада и быстрый поиск <a class="header-anchor" href="#фильтрация-склада-и-быстрыи-поиск" aria-label="Permalink to &quot;Фильтрация склада и быстрый поиск&quot;">​</a></h3><p>В верхней части экрана расположен трехсегментный фильтр состояния ассортимента:</p><ul><li><strong>«Все»:</strong> отображает полный перечень активных моделей мастерской, включая изделия с нулевым складским остатком (позволяет быстро запустить производство или обновить техкарту).</li><li><strong>«В наличии»:</strong> оставляет в списке исключительно те позиции, которые физически присутствуют на складе в данную секунду (<code>остаток &gt; 0</code>).</li><li><strong>«В архиве»:</strong> показывает архивные изделия, снятые с производства или временно выведенные из активного оборота.</li></ul><p>Строка поиска в правом углу снабжена кнопкой мгновенного сброса и выполняет фильтрацию на лету по названию изделия без перезагрузки экрана.</p><hr><h2 id="анатомия-складскои-строки-изделия" tabindex="-1">Анатомия складской строки изделия <a class="header-anchor" href="#анатомия-складскои-строки-изделия" aria-label="Permalink to &quot;Анатомия складской строки изделия&quot;">​</a></h2><p>Каждая строка складского реестра содержит исчерпывающий набор технологических, количественных и финансовых индикаторов:</p><ul><li><strong>Миниатюра изделия (1:1):</strong> квадратное превью высокого разрешения, автоматически подтягиваемое из технологической карты изделия или онлайн-витрины.</li><li><strong>Наименование модели:</strong> полное название изделия с быстрым переходом к редактированию или просмотру.</li><li><strong>Индикатор складского остатка:</strong> визуальный чип с цветовой индикацией. При наличии товара выводится зеленый статус (например, <em>«В наличии: 4 шт.»</em>), при нулевом остатке — нейтральный серый чип <em>«Нет на складе»</em>.</li><li><strong>Исторический счетчик выпуска:</strong> показатель <em>«Всего произведено: [X]»</em>, отражающий совокупный объем изделий данной модели, изготовленный мастерской за все время работы в системе.</li><li><strong>Специальные статусные бейджи:</strong><ul><li><strong>«В архиве»</strong> — технологическая карта перемещена в архивный реестр;</li><li><strong>«Без рецепта»</strong> — изделие оприходовано напрямую на склад без предварительного создания технологической карты.</li></ul></li></ul><p>В правой части строки расположен блок кнопок быстрого реагирования: переход в конструктор техкарты, вызов окна инвентаризации, перемещение позиции в архив или восстановление из архива.</p><hr><h2 id="физика-учета-двоиная-себестоимость-и-метод-первых-партии" tabindex="-1">Физика учета: Двойная себестоимость и метод первых партий <a class="header-anchor" href="#физика-учета-двоиная-себестоимость-и-метод-первых-партии" aria-label="Permalink to &quot;Физика учета: Двойная себестоимость и метод первых партий&quot;">​</a></h2><p>Главное отличие профессионального складского учета от любительских записей — строгое разделение текущих производственных затрат и фактической себестоимости уже изготовленных складских запасов.</p><p>На каждой карточке готового товара программа одновременно рассчитывает и отображает две самостоятельные величины себестоимости:</p><ol><li><strong>Себестоимость остатка (фактическая МАК):</strong> средневзвешенная стоимость тех конкретных изделий, которые физически лежат у вас на стеллаже. Она рассчитывается на основе замороженной себестоимости реальных партий, оприходованных с Верстака.</li><li><strong>По калькулятору (плановая расчетная):</strong> теоретическая стоимость производства единицы товара «прямо сейчас» исходя из актуальных складских цен на сырье и текущих тарифных ставок мастерской.</li></ol><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Физика складского учета</span><div class="formula-heading">Средневзвешенная себестоимость остатка готовой продукции</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Себестоимость остатка</span><span class="math-op">=</span><span class="math-var">Сумма замороженных стоимостей остатков партий</span><span class="math-op">÷</span><span class="math-var">Фактический физический остаток на складе</span></div></div></div><h3 id="метод-первых-партии-фифо-на-практике" tabindex="-1">Метод первых партий (ФИФО) на практике <a class="header-anchor" href="#метод-первых-партии-фифо-на-практике" aria-label="Permalink to &quot;Метод первых партий (ФИФО) на практике&quot;">​</a></h3><p>Для списания изделий при продаже или списании ОмниКрафт ЕРП использует <strong>метод первых партий (ФИФО)</strong>. Партии расходуются в строгой хронологической последовательности их создания.</p><div class="info custom-block"><p class="custom-block-title">Практический пример: Защита маржинальности от инфляции сырья</p><p>Представьте реальный производственный сценарий в мастерской:</p><ol><li>Месяц назад мастер изготовил партию из трех кожаных ремней. Сырье стоило недорого, и фактическая себестоимость каждого ремня зафиксировалась на отметке <code>1 800 ₽</code>. Изделия легли на склад.</li><li>Сегодня поставщик поднял цены на пряжки и кожу на 40%. Калькулятор показывает, что сшить такой же ремень сейчас стоит <code>2 500 ₽</code>.</li><li>В мастерскую приходит покупатель и забирает один ремень.</li></ol><p>Если бы программа автоматически усреднила себестоимость или пересчитала старый ремень по новым ценам Калькулятора, прибыль была бы искажена. ОмниКрафт ЕРП помнит историю: со склада спишется ремень из первой партии с себестоимостью ровно <code>1 800 ₽</code>. Это обеспечивает абсолютную чистоту управленческого баланса и точный расчет чистой прибыли.</p></div><hr><h2 id="рекомендуемая-розничная-цена-и-каналы-продаж" tabindex="-1">Рекомендуемая розничная цена и каналы продаж <a class="header-anchor" href="#рекомендуемая-розничная-цена-и-каналы-продаж" aria-label="Permalink to &quot;Рекомендуемая розничная цена и каналы продаж&quot;">​</a></h2><p>Под блоком себестоимости программа выводит расчетную розничную цену изделия. Программа определяет ее по двум взаимосвязанным сценариям:</p><ul><li><strong>Автоматический расчет по наценке:</strong> себестоимость умножается на установленный процент наценки. Приоритет имеет персональная наценка, заданная в технологической карте изделия. Если индивидуальная наценка не указана, применяется глобальная ставка наценки из Настроек пространства (по умолчанию <code>100%</code>).</li><li><strong>Приоритет фиксированной цены из каналов сбыта:</strong> если в таблице каналов продаж (например, для канала «Сайт» или маркетплейса) для изделия установлена фиксированная цена в рублях, программа выводит в качестве рекомендуемой цены именно это значение.</li></ul><p>Такой подход защищает мастера от случайных продаж ниже порога рентабельности при резких колебаниях закупочных цен на материалы.</p><hr><h2 id="прямое-оприходование-готовои-продукции" tabindex="-1">Прямое оприходование готовой продукции <a class="header-anchor" href="#прямое-оприходование-готовои-продукции" aria-label="Permalink to &quot;Прямое оприходование готовой продукции&quot;">​</a></h2><p>В ремесленной практике готовые изделия не всегда поступают исключительно через производственный цикл Верстака. Бывают ситуации, когда готовый товар требуется поставить на баланс напрямую.</p><p>В левой части панели инструментов расположена кнопка <strong>«Оприходовать товар»</strong>. Она открывает диалоговое окно прямой постановки изделий на складской учет.</p><ol class="craft-list-steps"><li><div><strong>Выбор номенклатуры:</strong><br> Выберите изделие из каталога или введите название. Если такое название уже есть в каталоге, партия поступит на существующую позицию. </div></li><li><div><strong>Количество принимаемых единиц:</strong><br> Объём партии готовой продукции, поступающий на складской баланс. </div></li><li><div><strong>Себестоимость единицы:</strong><br> Фиксация новой независимой партии по методике ФИФО. </div></li><li><div><strong>Розничная цена</strong><br> Если заполнить поле «Розничная цена (РРЦ, опционально)», программа сохранит цену канала «Сайт» вместе с партией. Публикацией изделия управляют в редакторе витрины. </div></li></ol><div class="info custom-block"><p class="custom-block-title">Модель складского изделия</p><p>В окне <strong>«Оприходовать товар»</strong> у новой или существующей позиции без техкарты можно заполнить поле <strong>«Модель изделия (линейка)»</strong>. Для позиции с техкартой используется модель, выбранная в Калькуляторе.</p></div><h3 id="сценарии-применения-прямого-оприходования" tabindex="-1">Сценарии применения прямого оприходования: <a class="header-anchor" href="#сценарии-применения-прямого-оприходования" aria-label="Permalink to &quot;Сценарии применения прямого оприходования:&quot;">​</a></h3><ol><li><strong>Ввод стартовых остатков:</strong> при начале работы в ОмниКрафт ЕРП, когда на полках мастерской уже лежит готовая продукция, изготовленная до внедрения программы.</li><li><strong>Давальческое и партнерское сырье:</strong> приемка изделий от смежных мастеров или дружественных студий для совместной реализации.</li><li><strong>Возврат выставочных образцов:</strong> возвращение изделий с фотосессий, ярмарок или витрин партнеров, если они временно списывались с баланса.</li></ol><div class="info custom-block"><p class="custom-block-title">Физика учета: Нулевое влияние на сырье и кассу</p><p>Прямое оприходование готовой продукции создает новую входящую партию на складе готовых изделий, но <strong>не расходует материалы со склада сырья</strong> и <strong>не создает расходных записей в кассе (ДДС)</strong>. Это операция чистого оприходования товарно-материальных ценностей.</p></div><hr><h2 id="инвентаризация-изделии-корректировка-остатков" tabindex="-1">Инвентаризация изделий: Корректировка остатков <a class="header-anchor" href="#инвентаризация-изделии-корректировка-остатков" aria-label="Permalink to &quot;Инвентаризация изделий: Корректировка остатков&quot;">​</a></h2><p>Реальная складская жизнь неизбежно вносит коррективы: изделие может получить повреждение при хранении, потеряться или обнаружиться при генеральной уборке цеха. Для устранения расхождений в каждой строке и карточке товара предусмотрена кнопка <strong>«Инвентаризация»</strong>.</p><p>Программа поддерживает два типа складской корректировки:</p><ol><li><strong>«Оприходовать излишек (+)»:</strong> увеличивает физический остаток изделия на складе. В поле «Себестоимость единицы» по умолчанию подставляется плановая себестоимость из Калькулятора, однако мастер может вручную скорректировать эту цифру. Программа формирует новую партию готовой продукции.</li><li><strong>«Списать недостачу (-)»</strong> уменьшает остаток на указанное число штук. Программа списывает самые старые партии по методу первых партий (ФИФО). Если недостача больше текущего остатка, пересчёт отклоняется и количество в партиях сохраняется.</li></ol><div class="warning custom-block"><p class="custom-block-title">Не подменяйте продажи списанием недостачи!</p><p>Списание недостачи удаляет изделие со склада без фиксации выручки. Если вы передали изделие заказчику, подарили постоянному клиенту в знак благодарности или сделали 100% скидку, <strong>всегда проводите это через раздел «Продажи»</strong> с нулевой ценой. В этом случае себестоимость изделия будет честно учтена в отчетах о прибылях и убытках как коммерческий расход на маркетинг, а не как безымянная потеря на складе.</p></div><hr><h2 id="управление-жизненным-циклом-архив-и-защита-капитала" tabindex="-1">Управление жизненным циклом: Архив и защита капитала <a class="header-anchor" href="#управление-жизненным-циклом-архив-и-защита-капитала" aria-label="Permalink to &quot;Управление жизненным циклом: Архив и защита капитала&quot;">​</a></h2><p>Ассортимент мастерской постоянно обновляется: устаревшие модели снимаются с производства, сезонные коллекции уступают место новым изделиям. В ОмниКрафт ЕРП реализована многоуровневая система архивации и защиты данных.</p><h3 id="отправка-изделия-в-архив" tabindex="-1">Отправка изделия в архив <a class="header-anchor" href="#отправка-изделия-в-архив" aria-label="Permalink to &quot;Отправка изделия в архив&quot;">​</a></h3><p>Чтобы скрыть позицию из активного списка:</p><ol><li>Нажмите кнопку <strong>«Отправить изделие в архив»</strong> (иконка архива) в правой части строки изделия.</li><li>Подтвердите архивацию. При незавершённом заказе сначала завершите выпуск партии или отмените задание.</li><li>Откройте фильтр <strong>«В архиве»</strong>, чтобы найти изделие. Его партии и остаток сохраняются и по ним можно проводить продажи. Для нового производственного заказа сначала восстановите позицию.</li></ol><div class="tip custom-block"><p class="custom-block-title">Технологическая карта сохраняется</p><p>При отправке товара в архив связанная с ним технологическая карта в разделе «Калькулятор» автоматически перемещается в категорию «Архив рецептов». Никакие расчеты, нормы расхода сырья и параметры времени не стираются. Вы можете в любой момент вернуть изделие в работу нажатием кнопки восстановления.</p></div><h3 id="восстановление-и-удаление" tabindex="-1">Восстановление и удаление <a class="header-anchor" href="#восстановление-и-удаление" aria-label="Permalink to &quot;Восстановление и удаление&quot;">​</a></h3><p>В режиме фильтрации <strong>«В архиве»</strong> доступны две операции:</p><ul><li><strong>Восстановить изделие (иконка возврата):</strong> изделие возвращается в активный каталог склада, а его технологическая карта снова становится доступной для запуска на Верстаке.</li><li><strong>«Удалить изделие»</strong> (иконка корзины) убирает позицию и связанную техкарту из каталога. История проведённых операций сохраняется.</li></ul><div class="warning custom-block"><p class="custom-block-title">Условия удаления</p><p>Удаление доступно при остатке <code>0 шт.</code> и отсутствии незавершённых производственных заказов. Если есть остаток, оформите продажу или внесите фактическую недостачу через инвентаризацию.</p></div><hr><h2 id="сводная-матрица-складских-операции" tabindex="-1">Сводная матрица складских операций <a class="header-anchor" href="#сводная-матрица-складских-операции" aria-label="Permalink to &quot;Сводная матрица складских операций&quot;">​</a></h2><p>Для быстрого ориентирования в финансово-складских последствиях действий используйте справочную матрицу:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Действие в программе</th><th style="text-align:left;">Склад материалов</th><th style="text-align:left;">Касса (ДДС)</th><th style="text-align:left;">Партии готовых товаров</th><th style="text-align:left;">Влияние на капитал цеха</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Выпуск с Верстака</strong></td><td style="text-align:left;">Списание сырья по нормам</td><td style="text-align:left;">Не изменяется</td><td style="text-align:left;">Создание новой партии ФИФО</td><td style="text-align:left;">Переток: Сырье ➔ Готовая продукция</td></tr><tr><td style="text-align:left;"><strong>Прямое оприходование</strong></td><td style="text-align:left;">Не изменяется</td><td style="text-align:left;">Не изменяется</td><td style="text-align:left;">Создание новой партии ФИФО</td><td style="text-align:left;">Увеличение товарного капитала</td></tr><tr><td style="text-align:left;"><strong>Инвентаризация: Излишек (+)</strong></td><td style="text-align:left;">Не изменяется</td><td style="text-align:left;">Не изменяется</td><td style="text-align:left;">Создание новой партии ФИФО</td><td style="text-align:left;">Увеличение товарного капитала</td></tr><tr><td style="text-align:left;"><strong>Инвентаризация: Недостача (-)</strong></td><td style="text-align:left;">Не изменяется</td><td style="text-align:left;">Не изменяется</td><td style="text-align:left;">Списание старых партий ФИФО</td><td style="text-align:left;">Уменьшение товарного капитала (убыток)</td></tr><tr><td style="text-align:left;"><strong>Продажа со склада</strong></td><td style="text-align:left;">Списание упаковки (тары)</td><td style="text-align:left;">Поступление выручки</td><td style="text-align:left;">Списание старых партий ФИФО</td><td style="text-align:left;">Рост ликвидности (ДДС) + прибыль</td></tr><tr><td style="text-align:left;"><strong>Перемещение в архив</strong></td><td style="text-align:left;">Не изменяется</td><td style="text-align:left;">Не изменяется</td><td style="text-align:left;">Сохраняются без изменений</td><td style="text-align:left;">Не изменяется</td></tr></tbody></table><hr><h2 id="разбор-внештатных-ситуации-troubleshooting" tabindex="-1">Разбор внештатных ситуаций (Troubleshooting) <a class="header-anchor" href="#разбор-внештатных-ситуации-troubleshooting" aria-label="Permalink to &quot;Разбор внештатных ситуаций (Troubleshooting)&quot;">​</a></h2><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">Что делать, если фактическое число изделий на полке не совпадает с цифрой в программе?</summary><div class="faq-content"><p>Откройте инвентаризацию на карточке товара и введите разницу в штуках. Для излишка укажите себестоимость единицы новой партии. Недостающие изделия списываются из самых ранних партий.</p></div></details><details class="faq-item"><summary class="faq-summary">Почему система не позволяет удалить товар из каталога?</summary><div class="faq-content"><p>Проверьте остаток и очередь производства. Архив позволяет убрать позицию из активного каталога до продажи остатка. Если по товару открыт производственный заказ, завершите или отмените его.</p></div></details><details class="faq-item"><summary class="faq-summary">Как восстановить случайно заархивированный товар?</summary><div class="faq-content"><p>Выберите фильтр «В архиве». Нажмите на карточке кнопку «Восстановить изделие в активный каталог». Позиция вернётся со всеми партиями и ценами.</p></div></details></div>',63))])}const y=a(g,[["render",p]]);export{v as __pageData,y as default};
